return $input.all().map(item => {
  const t = item.json;

  const categoria = (t.itilcategories_id || "")
    .replace(/&gt;/g, ">")
    .toUpperCase()
    .trim();

  const isProjeto = categoria.startsWith("PROJETO");

  return {
    json: {
      ...t, // ✅ mantém TODO o dado original
      categoria_normalizada: categoria,
      isProjeto: isProjeto
    }
  };
});

return $input.all().map(item => {
  const t = item.json;

  const tituloLimpo = (t.name || "Sem título")
    .split(">")
    .shift()
    .trim();

  return {
    json: {
      original: t,
      id: t.id,
      isProjeto: t.isProjeto,
      title: `#${t.id} - ${tituloLimpo}`
    }
  };
});

const PLAN_ID   = "CKYEqy96A0i5M_rIqD_Rh2UACONF";
const BUCKET_ID = "tPa8irp8aUKws8LPrQLgpmUABljo";

function mapPrioridade(p) {
  if (p >= 5) return 1;
  if (p == 4) return 3;
  if (p == 3) return 5;
  return 9;
}

return $input.all().map(item => {

  const t = item.json.original;

  const tecnico =
    t._users_id_assign?.[0]?.name ||
    t.users?.["2"]?.[0]?.name ||
    "Não atribuído";

  const dataISO = t.date
    ? new Date(t.date).toISOString()
    : undefined;

  return {
    json: {
      planId: PLAN_ID,
      bucketId: BUCKET_ID,

      title: item.json.title,

      priority: mapPrioridade(Number(t.priority)),

      startDateTime: dataISO,

      description: `
 Chamado: #${t.id}

 ${t.name || "Sem descrição"}

 Técnico: ${tecnico}
 Abertura: ${t.date || "—"}
 Prioridade: ${t.priority || "—"}
      `.trim(),

      isProjeto: item.json.isProjeto
    }
  };
});

// === Painel Gestão à Vista GLPI — visão macro (robusto) ===

const tickets = $('Tratativa de categoria').all().map(i => i.json);
const agora = Date.now();
const fmtData = d => d ? new Date(d).toLocaleDateString('pt-BR') : '—';

// ---------- Normalizadores (aceitam número OU texto) ----------
function nivelPrioridade(t) {
  const p = t.priority;
  const n = Number(p);
  if (String(p ?? '').trim() !== '' && !isNaN(n)) return n; // veio número
  const map = { 'muito baixa':1,'baixa':2,'média':3,'media':3,'normal':3,
                'alta':4,'muito alta':5,'maior':6,'major':6 };
  return map[String(p ?? '').toLowerCase().trim()] || 0;
}

function estaAberto(t) {
  const s = t.status;
  const n = Number(s);
  if (String(s ?? '').trim() !== '' && !isNaN(n)) return [1,2,3,4].includes(n); // 1 a 4 = aberto
  const str = String(s ?? '').toLowerCase().trim();
  const fechado = ['soluc','resolv','fechado','solved','closed'];
  if (fechado.some(x => str.includes(x))) return false;
  return true; // desconhecido => trata como aberto
}

function dataValida(v) {
  if (!v) return null;
  const s = String(v).trim();
  if (!s || s.startsWith('0000') || s.startsWith('1970')) return null;
  const d = new Date(s.replace(' ', 'T'));
  return isNaN(d.getTime()) ? null : d;
}

// Técnico atribuído — tenta vários formatos do GLPI
function tecnicoDe(t) {
  let a = t._users_id_assign;
  if (Array.isArray(a) && a.length) return a[0].name || a[0].login || a[0].realname || 'Não atribuído';
  if (a && typeof a === 'object') {
    const v = Object.values(a);
    if (v.length && v[0]) return v[0].name || v[0].login || v[0].realname || 'Não atribuído';
  }
  if (t.users && typeof t.users === 'object') {            // with_users keyed por tipo (2 = assign)
    const at = t.users['2'] || t.users[2];
    if (Array.isArray(at) && at.length) return at[0].name || at[0].login || 'Não atribuído';
  }
  if (typeof t.users_id_assign === 'string' && t.users_id_assign.trim()) return t.users_id_assign;
  if (typeof t.users_id_recipient === 'string' && t.users_id_recipient.trim()) return t.users_id_recipient;
  return 'Não atribuído';
}

// ---------- Agregações ----------
const abertos = tickets.filter(estaAberto);
const total = abertos.length;

// Distribuição por prioridade
const critica = abertos.filter(t => nivelPrioridade(t) >= 5).length; // Muito Alta / Maior
const alta    = abertos.filter(t => nivelPrioridade(t) === 4).length;
const media   = abertos.filter(t => nivelPrioridade(t) === 3).length;
const baixa   = abertos.filter(t => nivelPrioridade(t) > 0 && nivelPrioridade(t) <= 2).length;

// SLA vencido: prazo válido E no passado
const vencidos = abertos.filter(t => {
  const prazo = dataValida(t.time_to_resolve);
  return prazo && prazo.getTime() < agora;
}).length;

// Técnicos distintos com chamado em aberto
const tecnicosSet = new Set();
for (const t of abertos) {
  const nome = tecnicoDe(t);
  if (nome !== 'Não atribuído') tecnicosSet.add(nome);
}
const tecnicos = tecnicosSet.size;

// Sem responsável (gargalo de triagem)
const semResponsavel = abertos.filter(t => tecnicoDe(t) === 'Não atribuído').length;

// Top 5 mais antigos em aberto
const top5 = [...abertos].filter(t => dataValida(t.date))
  .sort((a, b) => dataValida(a.date) - dataValida(b.date))
  .slice(0, 5);

const top5Items = [];
for (const t of top5) {
  top5Items.push({ type: "TextBlock", text: `#${t.id} - ${t.name || 'Sem título'}`, wrap: true });
  top5Items.push({ type: "TextBlock", text: `👨‍💻 ${tecnicoDe(t)}  ·  📅 ${fmtData(t.date)}`, spacing: "None", isSubtle: true });
}
if (top5Items.length === 0) top5Items.push({ type: "TextBlock", text: "Nenhum chamado em aberto", isSubtle: true });

console.log(`Total:${total} Crítica:${critica} Alta:${alta} Média:${media} Baixa:${baixa} Vencidos:${vencidos} Técnicos:${tecnicos} SemResp:${semResponsavel}`);

// ---------- Adaptive Card ----------
const card = {
  type: "AdaptiveCard",
  $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
  version: "1.5",
  body: [
    { type: "TextBlock", text: "📊 Gestão à Vista GLPI", weight: "Bolder", size: "Large", color: "Accent" },
    { type: "TextBlock", text: fmtData(new Date()), spacing: "None", isSubtle: true },

    { type: "FactSet", facts: [
      { title: "📋 Total em aberto", value: String(total) },
      { title: "⏰ SLA vencido",      value: String(vencidos) },
      { title: "👨‍💻 Técnicos ativos", value: String(tecnicos) },
      { title: "🆕 Sem responsável",  value: String(semResponsavel) }
    ]},

    { type: "TextBlock", text: "⚠️ Por Prioridade", weight: "Bolder", separator: true },
    { type: "FactSet", facts: [
      { title: "🔴 Crítica (M.Alta/Maior)", value: String(critica) },
      { title: "🟠 Alta",  value: String(alta) },
      { title: "🟡 Média", value: String(media) },
      { title: "🟢 Baixa", value: String(baixa) }
    ]},

    { type: "TextBlock", text: "🔴 Top 5 Mais Antigos", weight: "Bolder", separator: true },
    { type: "Container", style: "attention", items: top5Items }
  ]
};

return [{
  json: {
    type: "message",
    attachments: [{ contentType: "application/vnd.microsoft.card.adaptive", content: card }]
  }
}];

// === Filtrar tickets que já viraram task no Planner ===

// 1) Tasks que já existem no plano (resposta do GET)
const resp = $('Buscar Tasks Planner').first().json;
const tasksExistentes = resp.value || [];

// 2) Conjunto com os IDs de ticket já presentes
//    (extraídos do título "Projeto #NNNNN - ...")
const idsExistentes = new Set();
for (const task of tasksExistentes) {
  const m = (task.title || '').match(/#(\d+)/);
  if (m) idsExistentes.add(m[1]);
}

// 3) Tickets de projeto vindos do GLPI
const tickets = $('Chamado com projeto').all();

// 4) Mantém só os que ainda NÃO têm task criada
const novos = tickets.filter(item => {
  const id = String(item.json.id || '');
  return id && !idsExistentes.has(id);
});

console.log(`Tickets de projeto: ${tickets.length} | Já existem: ${idsExistentes.size} | Novos a criar: ${novos.length}`);

return novos;
